/** Текст QA קטע (mkseg.sh 26.10). */
export const DEL_BODY = 'קטע בדיקה למחיקה עם הקראה';
/** Файл MP3 26.10: копия .qa/research/rec-pages/arvit-ashk-k4.mp3 в «Файлы» iPhone, ячейка во «Недавние» начинается с «arvit-ashk-k4». */
export const DEL_REC_FILE = 'arvit-ashk-k4.mp3';
export const DEL_REC_CELL = process.env.QA_REC_CELL || 'arvit-ashk-k4';
/** «מיקום ומחיקה» после пометки (544d9c-2610-after-delete.png). */
export const MARKED_FULL = 'הקטע מסומן למחיקה. עד האישור המשתמשים עדיין רואים אותו.';
export const MARKED_DRAFT = 'המחיקה נשמרה כטיוטה וממתינה לאישור.';
/** Окно после «אישור ופרסום השינוי» (544d9c-2610-approved.png). */
export const CHANGE_APPROVED = 'השינוי אושר ומוצג עכשיו למשתמשים.';
/** Подпись под полем «שם המאשר» (setapprover.py): поле — TextField прямо над ней. */
export const APPROVER_HINT = 'השם נשמר עם האישור';
/** Строка «היסטוריית אישורים» (544d9c-2610-history.png): «<заголовок>: הקטע נמחק ממקום 2, אושר על ידי בודק QA, 26.10.2026, 11:56». */
export const HISTORY_DELETED = (title: string, place: number) => `${title}: הקטע נמחק ממקום ${place}`;
export const HISTORY_BY = (who: string) => `אושר על ידי ${who}`;
/** Строка записи у пользователя (src2.xml 26.10). */
export const USER_REC_PREFIX = (who: string) => `הקראה: ${who} · `;
export const USER_NO_REC = 'אין הקראה לקטע הזה';
export const REC_APPROVED_TOAST = 'ההקראה אושרה ומוצעת עכשיו להשמעה בקטע הזה.';
export const REC_NOT_MATCHING_FULL = 'לא תואמת את הטקסט הנוכחי של הקטע';
export const EDIT_SUFFIX = ' (בדיקת QA)';

/** Заголовок QA קטע «QA-AUTO מחיקה עם הקראה д.м» (26.10) / «QA-AUTO מחיקה לא תואמת д.м». */
export const delTitle = (kind: 'עם הקראה' | 'לא תואמת') => `QA-AUTO מחיקה ${kind} ${new Date().getDate()}.${new Date().getMonth() + 1}`;

// ───────────────────────── поля и окна ─────────────────────────

/** «שם המאשר»: iOS — TextField прямо над подписью «השם נשמר עם האישור…» (setapprover.py 26.10; в поле по умолчанию «מנהל תוכן»).
 *  Android — поле после подписи «שם המאשר». Проверяет, что значение записалось. */
export async function setApprover(name: string) {
  if (driver.isAndroid) { await setField('שם המאשר', name); return; }
  await scrollToText('שם המאשר');
  const hint = await $(`-ios predicate string:label BEGINSWITH "${APPROVER_HINT}"`);
  await hint.waitForExist({ timeout: 15000 });
  const hy = (await hint.getLocation()).y;
  let best: El | null = null; let bestY = -Infinity;
  for (const e of await $$('-ios class chain:**/XCUIElementTypeTextField').getElements()) {
    const { y } = await e.getLocation();
    if (y < hy && y > bestY) { bestY = y; best = e as unknown as El; }
  }
  if (!best) throw new Error('поле «שם המאשר» (над «השם נשמר עם האישור…») не найдено');
  await best.clearValue();
  await best.setValue(name);
  await driver.waitUntil(async () => String((await best!.getAttribute('value')) ?? '') === name,
    { timeout: 5000, timeoutMsg: `«שם המאשר» не стал «${name}»` });
}

/** Кнопка label внутри окна с заголовком, начинающимся на titlePrefix: ближайшая НИЖЕ заголовка (≤ 500 pt). */
export async function dialogButton(titlePrefix: string, label: string): Promise<El> {
  let title: { y: number } | undefined;
  await driver.waitUntil(async () => {
    title = (await nodes()).find((n) => n.label.startsWith(titlePrefix));
    return !!title;
  }, { timeout: 30000, interval: 700, timeoutMsg: `нет окна «${titlePrefix}…»` });
  const els = await $$(driver.isAndroid
    ? `android=new UiSelector().text("${label}")`
    : `-ios predicate string:type == "XCUIElementTypeButton" AND (name == "${label}" OR label == "${label}")`).getElements();
  let best: El | null = null; let bestDy = Infinity;
  for (const e of els) {
    const { y } = await e.getLocation();
    const dy = y - title!.y;
    if (dy > 0 && dy < 500 && dy < bestDy) { bestDy = dy; best = e as unknown as El; }
  }
  if (!best) throw new Error(`в окне «${titlePrefix}…» нет кнопки «${label}»`);
  return best;
}

/** «אישור ופרסום» текста: «שם המאשר» → кнопка → окно «הקטע אושר ומוצג עכשיו למשתמשים.» → «אישור» из окна. */
export async function publishText(approver: string, marker: string) {
  await setApprover(approver);
  await setField('הערה לאישור (לא חובה)', marker).catch(() => {});
  await scrollToText('אישור ופרסום');
  await tapLowest('אישור ופרסום');                         // у карточки заголовок и кнопка с тем же текстом
  await (await dialogButton(ADM_PUBLISHED, 'אישור')).click();
}

/** Экран молитвы: самая нижняя «+ הוספת קטע כאן» → «קטע חדש» → заголовок, текст → «אישור ופרסום» (как mkseg.sh 26.10). */
export async function addQaSegment(title: string, body: string, approver: string, marker: string) {
  await scrollToText('קטעי התפילה');
  let last: El | null = null;
  for (let i = 0; i < 8; i++) {
    const all = await $$(driver.isAndroid
      ? `android=new UiSelector().descriptionContains("${ADM_ADD_HERE}")`
      : `-ios predicate string:type == "XCUIElementTypeButton" AND (name CONTAINS "${ADM_ADD_HERE}" OR label CONTAINS "${ADM_ADD_HERE}")`).getElements();
    if (all.length) { last = all[all.length - 1] as unknown as El; if (await last.isDisplayed().catch(() => false)) break; }
    await swipeUp();
  }
  if (!last) last = (await buttonContaining(ADM_ADD_HERE)) as unknown as El;
  await last.click();
  await (await byText(ADM_NEW_TITLE)).waitForExist({ timeout: 20000 });
  await setField('כותרת הקטע', title);
  await setField('טקסט התפילה', body);
  await publishText(approver, marker);
}

/** Загрузить MP3 arvit-ashk-k4 в открытый «עריכת קטע» («מי הקליט» = approver). false — файла нет в «Недавние». */
export async function uploadK4(recordedBy = REC_APPROVER): Promise<boolean> {
  if (!(await uploadRecordingAny(DEL_REC_FILE, recordedBy, { labelPrefix: DEL_REC_CELL, cancelIfMissing: true }))) return false;
  await (await byTextContains(REC_PENDING_FULL)).waitForExist({ timeout: 120000 });
  return true;
}

/** «מחיקת הקטע» (блок «מיקום ומחיקה») → окно «למחוק את הקטע «…»?». */
export async function openDeleteDialog(title: string) {
  await (await scrollToText(ADM_DELETE)).click();
  await (await byText(ADM_DELETE_TITLE(title))).waitForExist({ timeout: 10000 });
}

/** Ждать итог «מחיקת הקטע» в окне: пометка (MARKED_FULL) или старая ошибка #544d9c. */
export async function deleteOutcome(): Promise<'marked' | 'error'> {
  let res: 'marked' | 'error' = 'marked';
  await driver.waitUntil(async () => {
    if (await shown(byTextContains(ADM_STALE_ERROR))) { res = 'error'; return true; }
    return shown(byTextContains(MARKED_FULL));
  }, { timeout: 20000, interval: 700, timeoutMsg: `после «${ADM_DELETE}» нет ни «${MARKED_FULL}», ни сообщения об ошибке` });
  return res;
}

/** «אישור ופרסום השינוי»: «שם המאשר» → кнопка → окно «השינוי אושר ומוצג עכשיו למשתמשים.» → «אישור» из окна. */
export async function approveChange(approver: string, marker: string) {
  await setApprover(approver);
  await setField('הערה לאישור (לא חובה)', marker).catch(() => {});
  await (await scrollToText(ADM_APPROVE_CHANGE)).click();
  await (await dialogButton(CHANGE_APPROVED, 'אישור')).click();
  await driver.waitUntil(async () => !(await shown(byText(CHANGE_APPROVED))),
    { timeout: 15000, timeoutMsg: `окно «${CHANGE_APPROVED}» не закрылось` });
}

/** Строка «היסטוריית אישורים» об удалении (на экране молитвы в админке). */
export async function historyHasDeletion(title: string, place: number, approver: string) {
  await scrollToText('היסטוריית אישורים');
  const want = HISTORY_DELETED(title, place);
  for (let i = 0; i < 6; i++) {
    const hit = (await nodes()).find((n) => n.label.includes(want));
    if (hit) return hit.label.includes(HISTORY_BY(approver)) ? hit.label : '';
    await swipeUp();
  }
  return '';
}

/**
 * Уборка QA קטע 26.10 (after(), и при падении): нет строки — ничего. Иначе: уже «מסומן למחיקה» → только утверждение;
 * иначе «מחיקת הקטע» ПРЯМО с записью (поведение после #544d9c); если вдруг вернулась старая ошибка — «הסרת ההקראה» и повтор
 * (регресс #544d9c отмечается в логе). Возвращает счётчик «N מתוך M» и сводку записей после уборки.
 */
export async function cleanupDelSegment(title: string, approver = REC_APPROVER, marker = `QA-AUTO cleanup ${title}`) {
  await openRecAdminPrayer('уборка 26.10');
  if (await hasSectionRow(title)) {
    await openSection(title);
    if (!(await shown(byTextContains(MARKED_FULL)))) {
      const closeErr = async () => { const ok = await $('-ios predicate string:type == "XCUIElementTypeButton" AND label == "אישור"'); if (await ok.isExisting().catch(() => false)) await ok.click().catch(() => {}); };
      await closeErr();
      await openDeleteDialog(title);
      await (await dialogButton('למחוק את הקטע', ADM_DELETE)).click();
      if ((await deleteOutcome()) === 'error') {
        console.warn(`[2610] уборка: «${ADM_STALE_ERROR}» — регресс #544d9c; снимаю запись и удаляю повторно`);
        await closeErr();
        await removeRecordingWithDialog();
        await openDeleteDialog(title);
        await (await dialogButton('למחוק את הקטע', ADM_DELETE)).click();
        await expect(byTextContains(MARKED_FULL)).toBeExisting({ wait: 20000 });
      }
    }
    await approveChange(approver, marker);
    await openRecAdminPrayer('уборка 26.10: проверка');
    if (await hasSectionRow(title)) throw new Error(`уборка: «${title}» остался — убрать вручную`);
  }
  const count = await approvedCount();
  const summary = await recordingSummary();
  return { count, summary };
}
